import math
nodes = {p:i for i,p in enumerate(I4l)}
edges=[]
for a,b in pairs:
    w = math.hypot(b[0]-a[0], b[1]-a[1])
    edges.append((w,a,b))
# MST via kruskal
par = list(range(len(I4l)))
def find(x):
    while par[x]!=x: par[x]=par[par[x]]; x=par[x]
    return x
mst=set()
for w,a,b in sorted(edges):
    ra,rb=find(nodes[a]),find(nodes[b])
    if ra!=rb: par[ra]=rb; mst.add((a,b))
drawnset = {(a,b) for a,b,_ in drawn}
print("MST edges:", len(mst), "in drawn:", len(mst & drawnset))
print("MST not drawn:", len(mst - drawnset))
print("drawn not MST:", len(drawnset - mst))
# relative neighborhood graph: edge exists if no c with max(d(a,c),d(b,c)) < d(a,b)
rng=set()
for w,a,b in edges:
    da = math.hypot(b[0]-a[0],b[1]-a[1])
    if not any(math.hypot(c[0]-a[0],c[1]-a[1])<da and math.hypot(c[0]-b[0],c[1]-b[1])<da for c in I4l if c!=a and c!=b):
        rng.add((a,b))
print("RNG edges:", len(rng), "in drawn:", len(rng&drawnset), "drawn not in RNG:", len(drawnset-rng), "RNG not drawn:", len(rng-drawnset))

