def fill2(I, dirs):
    from collections import Counter
    vals = Counter(I.flatten()); bg = vals.most_common(1)[0][0]
    dots = {v for v in vals if v!=bg}
    H,W = I.shape
    P = I.copy()
    for r in range(H):
        for c in range(W):
            if I[r,c]!=bg: continue
            for dr,dc in dirs:
                # check both sides
                side1 = side2 = False
                for s in (1,-1):
                    rr,cc = r+s*dr, c+s*dc
                    while 0<=rr<H and 0<=cc<W:
                        if I[rr,cc] in dots: 
                            if s==1: side1=True
                            else: side2=True
                            break
                        rr+=s*dr; cc+=s*dc
                if side1 and side2:
                    P[r,c]=3; break
    return P
for name,dirs in [("H",[(0,1)]),("HV",[(0,1),(1,0)]),("HV+diag",[ (0,1),(1,0),(1,1),(1,-1)]),("ALL",[(0,1),(1,0),(1,1),(1,-1)])]:
    P = fill2(I, dirs)
    mm = I!=4
    print(name, "mismatch:", (P[mm]!=O[mm]).sum(), "of", mm.sum())
